import{z as n,x as r,o,c as i,q as d,j as s,D as a,d as l,s as c,S as t}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"ELF 加载","description":"","frontmatter":{"title":"ELF 加载","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exec-loading-elf.md","filePath":"cs/exec-loading-elf.md","lastUpdated":1791413859000}'),A={name:"cs/exec-loading-elf.md"};function B(p,e,_,T,f,m){const E=r("Mermaid");return o(),i("div",null,[e[2]||(e[2]=d('<h1 id="elf-加载" tabindex="-1">ELF 加载 <a class="header-anchor" href="#elf-加载" aria-label="Permalink to &quot;ELF 加载&quot;">​</a></h1><div class="epigraph"><p>内核读程序头，按段 `mmap` 进地址空间，设入口；动态则把解释器 `ld.so` 一并映射，由它完成重定位与构造器。</p><footer>—— 据 System V ABI；Linux `fs/binfmt_elf.c` 传统行为；主干[加载与动态链接](/cs/load-dynlink)；Levine 整理</footer></div><p>上一课<a href="/cs/elf-format">ELF 格式</a> 给出表。缺口是<strong>执行</strong>：<code>execve</code> 之后谁映射谁跳。主干加载课有直觉。本课钉内核 vs <code>ld.so</code> 分工、ASLR、辅助向量 <code>auxv</code>。交叉编译下一课收束链接课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>ET_EXEC</code> 固定地址（现代少）；<code>ET_DYN</code> PIE 随机基址。内核：映射 <code>PT_LOAD</code>，处理 <code>PT_INTERP</code>、栈上放 <code>argv</code>/<code>envp</code>/<code>auxv</code>。<code>ld.so</code>：找 <code>.so</code>、写 GOT、跑 <code>DT_INIT</code>。缺口是<strong>这条启动链</strong>，不是节头字段表。</p><p>栈权限、NX、RELRO 在加载时落实。</p><h3 id="加载不是解释字节码" tabindex="-1">加载不是解释字节码 <a class="header-anchor" href="#加载不是解释字节码" aria-label="Permalink to &quot;加载不是解释字节码&quot;">​</a></h3><p>映射后跳到机器入口。字节码 VM 是后一单元。不要把 <code>ld.so</code> 当 JVM。</p><p><span class="marginnote">binfmt_elf。SysV。主干 load-dynlink。本课补内核视角与 auxv（AT_PHDR、AT_ENTRY、AT_RANDOM）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 <code>readelf -l</code> 与 <code>/proc/self/maps</code>。动态：<code>LD_DEBUG=files</code> 看搜索。静态：无 interp，内核跳 <code>e_entry</code>。</p>',11)),(o(),s(t,null,{default:a(()=>[c(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXEC%5B%22execve%22%5D%20--%3E%20KERN%5B%22%E5%86%85%E6%A0%B8%E6%98%A0%E5%B0%84%20PT_LOAD%22%5D%0A%20%20KERN%20--%3E%20INT%7B%22%E6%9C%89%20PT_INTERP%3F%22%7D%0A%20%20INT%20--%3E%7C%E6%98%AF%7C%20LDSO%5B%22ld.so%20%E7%BB%91%E5%AE%9A%22%5D%0A%20%20INT%20--%3E%7C%E5%90%A6%7C%20ENT%5B%22%E8%B7%B3%20e_entry%22%5D%0A%20%20LDSO%20--%3E%20ENT%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<p><span class="marginnote">术语翻译：auxv（辅助向量）就是内核塞给新程序的一叠「便签条」：除了 argv 参数与 envp 环境变量，再附送几条关键情报——程序头表在哪（AT_PHDR）、入口在哪（AT_ENTRY）、一小撮随机字节（AT_RANDOM）供栈保护用。<code>ld.so</code> 靠这叠便签开工，不用自己再摸内存。</span></p><p>与<a href="/cs/stack-unwinding">unwind</a>：加载器注册的对象列表供展开器找 FDE。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>失败：找不到 <code>.so</code>、重定位溢出、栈执行被拒。setuid 忽略部分环境（<code>LD_PRELOAD</code>）——安全点名。不要在 setuid 路径依赖预加载。</p>',4)),(o(),s(t,null,{default:a(()=>[c(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22%E7%A8%8B%E5%BA%8F%E5%A4%B4%20PT_LOAD%20%E9%80%90%E9%A1%B9%E5%A4%84%E7%90%86%22%5D%20--%3E%20MAP%5B%22%E6%8C%89%20p_vaddr%20mmap%20%E8%BF%9B%E5%9C%B0%E5%9D%80%E7%A9%BA%E9%97%B4%22%5D%0A%20%20MAP%20--%3E%20TXT%5B%22%E4%BB%A3%E7%A0%81%E6%AE%B5%EF%BC%9AR%2BX%EF%BC%8C%E6%96%87%E4%BB%B6%E9%A1%B5%E6%98%A0%E5%B0%84%22%5D%0A%20%20MAP%20--%3E%20DAT%5B%22%E6%95%B0%E6%8D%AE%E6%AE%B5%EF%BC%9ARW%EF%BC%8C%E6%96%87%E4%BB%B6%E9%A1%B5%E6%98%A0%E5%B0%84%22%5D%0A%20%20DAT%20--%3E%20BSS%5B%22.bss%20%E6%97%A0%E6%96%87%E4%BB%B6%E5%86%85%E5%AE%B9%EF%BC%8C%E7%94%A8%E5%8C%BF%E5%90%8D%E9%A1%B5%E6%B8%85%E9%9B%B6%22%5D%0A%20%20PH%20--%3E%20STK%5B%22%E5%8F%A6%E5%BB%BA%E6%A0%88%EF%BC%8C%E5%8E%8B%E5%85%A5%20argc%2Fargv%2Fenvp%2Fauxv%22%5D%0A%20%20STK%20--%3E%20JMP%5B%22%E5%B0%B1%E7%BB%AA%EF%BC%8C%E8%B7%B3%E5%88%B0%E5%85%A5%E5%8F%A3%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p><span class="marginnote">数字实例：段按页（通常 4 KB）对齐映射，要求 <code>p_offset</code> 与 <code>p_vaddr</code> 对 0x1000 取模相等——所以常看到代码段文件偏移 0x1000、虚拟地址 0x401000。一个几百 KB 的可执行文件，映射只建立页表项，代码页等真正访问时缺页才从磁盘调入。</span></p><p>构造器顺序：与跨 <code>.so</code> 依赖有关，陷阱。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 <code>mmap</code> 系统课全文。后课默认：ELF 由内核+ld.so 加载。下一课交叉编译与三元组：生成哪一种 ELF。</p><p>也不把加载当浏览器加载 URL。</p><p><span class="marginnote">常见误区：初学者以为 <code>execve</code> 之后整个可执行文件已被「读进内存」——其实内核只建了映射，代码页要等第一次访问、缺页才从文件读入。也别把 <code>ld.so</code> 当 JVM 那样的解释器：它做的是找库、修 GOT、跑重定位，最终跳进去执行的是本机机器码。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核映射段并设栈；动态把控制交给 ld.so。</li><li>PIE/ASLR 改基址，重定位必须 PIC。</li><li>auxv 把phdr 与随机数传给用户态。</li><li>出处：ELF/SysV；Linux binfmt_elf；Levine；主干 load-dynlink。</li></ul>',8))])}const u=n(A,[["render",B]]);export{h as __pageData,u as default};
